/**
 * A Blind Feast
 * -------------
 * Elisha strikes the Aramean raiders with blindness, leads them into Samaria, and opens their eyes at a feast before sending them home. Stage: a great hall at night, lanterns, blindfolded warriors led to a table, then seeing in amazement; warm feast light, an astonishing mercy.
 *
 * Palette 0x241a10 → 0x060402 · light: ember · hero: house
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./elisha-kit.js.
 */

import { THREE, createScene, house, person } from './elisha-kit.js';

const BG = 0x241a10;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 621355734, bg: BG, fogNear: 45, fogFar: 180 });

    /* light — ember */
    W.lights({ sky: 0x3a2418, gnd: 0x1a0e08, hemi: 0.4, sun: 0xff7a30, sunI: 0.7, sunPos: [20, 26, 30] });

    W.stars(90, 150, [0xf0e0c8, 0xd8c0a0], 0.7);
    W.disc([0, 34, -150], 14, 0xff8a30, 0.12);

    /* ground */
    W.ground(260, 260, 0, 0, 0x060402, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* hero: the house */
    house(W, group, 0, 0, -2, 1.3, { mud: 0x060402 });

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0x8a6a44, head: 'wrap', wrap: 0x291e12, wrapTrim: 0x19120b, beard: 'long', staff: 'planted', ry: -0.53, s: 1.12 });

    return W.finish();
}

export default { build };
